package main

import (
	_ "embed"
	"encoding/json"
	"log"

	"github.com/gin-gonic/gin"
)

// vehicle_stats.json is generated by tools/vehicle-stats/extract.py from the installed vehicle mods
// prefabs (seats, armament, mass, hull). Served as-is.
//
//go:embed vehicle_stats.json
var vehicleStatsRaw []byte

func getVehicleStats(c *gin.Context) {
	c.Header("Cache-Control", "public, max-age=3600")
	c.Data(200, "application/json; charset=utf-8", vehicleStatsRaw)
}

func init() {
	if !json.Valid(vehicleStatsRaw) {
		log.Println("vehicle_stats.json: invalid JSON")
	}
}
